// ꘇ The Moon: a cut-paper silhouette film (adapted from the Artist Model Studio explainer, board 4.1).
// A puppet of 16 hinged pieces, a lightbox, layers of set and a table of keyframes that is photographed on threes.
// A self-contained vignette: no parameters, no inputs, it just plays and loops.
const fps = 8; // exposures a second: the puppet is photographed on threes (24 would be smooth)
const loop = true;
const size = renderer.getDrawingBufferSize(new THREE.Vector2());
const W = size.x || 960, H = size.y || 540, FRAME = 7; // FRAME: the height the film camera sees, in puppet units
const world = new THREE.Scene(); // the paper world; the host `scene` only shows its picture
const film = new THREE.OrthographicCamera((-FRAME * W) / H / 2, (FRAME * W) / H / 2, FRAME / 2, -FRAME / 2, 0.1, 50);
film.position.set(0, 0, 10);

// --- the lightbox: a glowing sheet behind everything, and the moon,
// which is a hole in the paper -------------------
const lightbox = new THREE.Mesh(
  new THREE.PlaneGeometry(40, 24),
  new THREE.MeshBasicMaterial({ map: glow(), depthWrite: false }),
);
lightbox.position.z = -5;
world.add(lightbox);
const moonDisc = new THREE.Mesh(
  new THREE.CircleGeometry(0.9, 48),
  new THREE.MeshBasicMaterial({
    color: 0xffffff,
    transparent: true,
    opacity: 0.95,
  }),
);
moonDisc.position.set(3.4, 2.1, -4.9);
world.add(moonDisc);
function glow() {
  // the lightbox: bright in the middle, falling off at the edges
  const c = document.createElement('canvas');
  c.width = c.height = 512;
  const g = c.getContext('2d'),
    r = g.createRadialGradient(256, 256, 20, 256, 256, 360);
  r.addColorStop(0, '#ffffff');
  r.addColorStop(0.55, '#bdbdbd');
  r.addColorStop(1, '#4a4a4a');
  g.fillStyle = r;
  g.fillRect(0, 0, 512, 512);
  return new THREE.CanvasTexture(c);
}

// --- paper
// -----------------------------------------------------------------------------------------------------
const paper = (color = 0x0b0a0a, opacity = 1) =>
  new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: opacity === 1,
  });
const BLACK = paper();
const cut = (shape, z, mat = BLACK) => {
  const m = new THREE.Mesh(new THREE.ShapeGeometry(shape, 24), mat);
  m.position.z = z;
  return m;
};

// A tapered limb with rounded ends, hanging from the origin down to
// -len (the hinge is the top circle's centre).
function limb(len, w0, w1) {
  const s = new THREE.Shape();
  s.absarc(0, 0, w0 / 2, Math.PI, 0, true);
  s.lineTo(w1 / 2, -len);
  s.absarc(0, -len, w1 / 2, 0, Math.PI, true);
  s.lineTo(-w0 / 2, 0);
  return s;
}
// This puppet is a stick figure: the body is two limbs standing up, as
// thin as the arms and legs (seen from the side there is
// no pelvis or shoulder to see). A rounded piece of paper from its
// hinge up to its far end.
function stick(len, w0, w1) {
  const s = new THREE.Shape();
  s.absarc(0, 0, w0 / 2, Math.PI, 0, false);
  s.lineTo(w1 / 2, len);
  s.absarc(0, len, w1 / 2, 0, Math.PI, false);
  s.lineTo(-w0 / 2, 0);
  return s;
}
const pelvis = () => stick(0.4, 0.26, 0.2); // the hips: the legs hang from here
const chest = () => stick(0.74, 0.2, 0.17); // up to the shoulders: the arms and the neck
function head() {
  // a profile, facing right: chin, lips, a small pointed nose, a soft
  // brow, a rounded skull
  const s = new THREE.Shape();
  s.moveTo(0.05, 0);
  s.lineTo(0.12, 0.04);
  s.lineTo(0.15, 0.1); // the chin
  s.lineTo(0.125, 0.145);
  s.lineTo(0.14, 0.185); // under the lip, the lips
  s.lineTo(0.125, 0.23);
  s.lineTo(0.285, 0.305); // under the nose, and its point
  s.bezierCurveTo(0.2, 0.33, 0.16, 0.36, 0.15, 0.4); // the bridge eases into the brow
  s.bezierCurveTo(0.15, 0.5, 0.12, 0.66, 0.0, 0.72); // a sloping forehead and the top of the head
  s.bezierCurveTo(-0.16, 0.76, -0.3, 0.6, -0.25, 0.4); // the back of the skull
  s.bezierCurveTo(-0.22, 0.25, -0.17, 0.12, -0.08, 0.0); // down to the neck
  return s;
}
function hand() {
  // a mitten: a palm that widens a little, a thumb tucked against it
  const s = new THREE.Shape();
  s.moveTo(-0.05, 0);
  s.lineTo(0.05, 0);
  s.bezierCurveTo(0.09, -0.05, 0.11, -0.09, 0.115, -0.13); // the thumb: a soft bump on the front edge
  s.bezierCurveTo(0.12, -0.17, 0.1, -0.2, 0.085, -0.22);
  s.bezierCurveTo(0.06, -0.31, -0.06, -0.31, -0.07, -0.2);
  s.lineTo(-0.06, -0.08);
  return s;
}
function foot() {
  // a slipper: a heel, a sole, and a toe that curls up
  const s = new THREE.Shape();
  s.moveTo(-0.1, 0.1);
  s.lineTo(0.22, 0.04);
  s.bezierCurveTo(0.4, 0.02, 0.5, 0.05, 0.56, 0.2);
  s.bezierCurveTo(0.5, 0.0, 0.42, -0.1, 0.3, -0.11);
  s.lineTo(-0.1, -0.12);
  s.lineTo(-0.1, 0.1);
  return s;
}
const neck = () => stick(0.22, 0.11, 0.09);

// Each part: where its hinge is (in its parent), its shape, its tip
// (where you grab it: the far end), how far it may turn.
// A hinge turns its part to point at the pointer, so any part, whatever
// its shape, is moved the same way.
const PARTS = [
  {
    id: 'pelvis',
    at: [0, 0],
    shape: pelvis(),
    tip: [0, 0.4],
    limit: [-0.5, 0.5],
    z: 0.02,
  },
  {
    id: 'chest',
    parent: 'pelvis',
    at: [0, 0.4],
    shape: chest(),
    tip: [0, 0.74],
    limit: [-0.7, 0.7],
    z: 0.022,
  },
  {
    id: 'neck',
    parent: 'chest',
    at: [0.02, 0.76],
    shape: neck(),
    tip: [0, 0.22],
    limit: [-0.5, 0.5],
    z: 0.025,
  },
  {
    id: 'head',
    parent: 'neck',
    at: [0, 0.2],
    shape: head(),
    tip: [0.03, 0.5],
    limit: [-0.7, 0.7],
    z: 0.03,
  },
  {
    id: 'armA',
    parent: 'chest',
    at: [0, 0.68],
    shape: limb(0.62, 0.17, 0.12),
    tip: [0, -0.62],
    limit: [-3.1, 3.1],
    z: 0.04,
  },
  {
    id: 'foreA',
    parent: 'armA',
    at: [0, -0.62],
    shape: limb(0.58, 0.12, 0.09),
    tip: [0, -0.58],
    limit: [-0.1, 2.7],
    z: 0.05,
  },
  {
    id: 'handA',
    parent: 'foreA',
    at: [0, -0.58],
    shape: hand(),
    tip: [0, -0.26],
    limit: [-1.0, 1.0],
    z: 0.06,
  },
  {
    id: 'armB',
    parent: 'chest',
    at: [0, 0.68],
    shape: limb(0.62, 0.17, 0.12),
    tip: [0, -0.62],
    limit: [-3.1, 3.1],
    z: -0.04,
  },
  {
    id: 'foreB',
    parent: 'armB',
    at: [0, -0.62],
    shape: limb(0.58, 0.12, 0.09),
    tip: [0, -0.58],
    limit: [-0.1, 2.7],
    z: -0.05,
  },
  {
    id: 'handB',
    parent: 'foreB',
    at: [0, -0.58],
    shape: hand(),
    tip: [0, -0.26],
    limit: [-1.0, 1.0],
    z: -0.06,
  },
  {
    id: 'thighA',
    parent: 'pelvis',
    at: [0, 0],
    shape: limb(0.85, 0.26, 0.16),
    tip: [0, -0.85],
    limit: [-1.5, 1.5],
    z: 0.01,
  },
  {
    id: 'shinA',
    parent: 'thighA',
    at: [0, -0.85],
    shape: limb(0.85, 0.16, 0.08),
    tip: [0, -0.85],
    limit: [-3.05, 0.1],
    z: 0.015,
  },
  {
    id: 'footA',
    parent: 'shinA',
    at: [0, -0.85],
    shape: foot(),
    tip: [0.5, 0.02],
    limit: [-1.3, 1.3],
    z: 0.02,
  },
  {
    id: 'thighB',
    parent: 'pelvis',
    at: [0, 0],
    shape: limb(0.85, 0.26, 0.16),
    tip: [0, -0.85],
    limit: [-1.5, 1.5],
    z: -0.01,
  },
  {
    id: 'shinB',
    parent: 'thighB',
    at: [0, -0.85],
    shape: limb(0.85, 0.16, 0.08),
    tip: [0, -0.85],
    limit: [-3.05, 0.1],
    z: -0.015,
  },
  {
    id: 'footB',
    parent: 'shinB',
    at: [0, -0.85],
    shape: foot(),
    tip: [0.5, 0.02],
    limit: [-1.3, 1.3],
    z: -0.02,
  },
];
const puppet = new THREE.Group();
const home = new THREE.Vector2(-1.2, -3.0); // where the puppet stands: drag the body to move it
puppet.position.set(home.x, home.y, 0);
puppet.scale.setScalar(1.35);
world.add(puppet);
const node = {};
for (const p of PARTS) {
  const g = new THREE.Group();
  g.position.set(p.at[0], p.at[1], 0);
  const m = cut(p.shape, p.z);
  g.add(m);
  const pin = new THREE.Mesh(
    new THREE.RingGeometry(0.035, 0.06, 20),
    new THREE.MeshBasicMaterial({ color: 0xffffff }),
  );
  pin.position.z = p.z + 0.2;
  g.add(pin);
  (p.parent ? node[p.parent].group : puppet).add(g);
  node[p.id] = {
    ...p,
    group: g,
    mesh: m,
    pin,
    pose: 0,
    depth: p.parent ? node[p.parent].depth + 1 : 0,
  };
}
node.pelvis.group.position.y = 1.75; // the hip joint: the legs hang from it, the body rises from it
const REST = {
  armA: 0.5,
  foreA: 0.7,
  armB: -0.4,
  foreB: 0.4,
  thighA: 0.2,
  thighB: -0.15,
  shinA: -0.1,
  shinB: -0.1,
  head: 0.05,
};
for (const [id, a] of Object.entries(REST)) node[id].pose = a;

// --- the set: layers of cut paper at different depths, a lightbox
// behind ---------------------------------------
const ridge = (y, amp, freq, phase, depth) => {
  const s = new THREE.Shape();
  s.moveTo(-14, -6);
  for (let x = -14; x <= 14; x += 0.4)
    s.lineTo(
      x,
      y +
        amp * Math.sin(x * freq + phase) +
        0.35 * amp * Math.sin(x * freq * 2.7 + phase * 2),
    );
  s.lineTo(14, -6);
  s.lineTo(-14, -6);
  return s;
};
const far = cut(
  ridge(-1.4, 0.7, 0.33, 0.3),
  -3.2,
  paper(0x3a3226, 0.55),
); // tissue: the light comes through it
const mid = cut(
  ridge(-2.2, 0.8, 0.26, 2.1),
  -1.8,
  paper(0x1a1610, 0.9),
);
const ground = cut(ridge(-3.05, 0.14, 0.9, 0), -0.3);
const reeds = new THREE.Group();
for (let i = 0; i < 26; i++) {
  // foreground grasses, nearer than the puppet
  const x = -9 + i * 0.7 + 0.3 * Math.sin(i * 7.1),
    h = 1 + 0.9 * Math.abs(Math.sin(i * 3.3)),
    lean = 0.3 * Math.sin(i * 5.3);
  const s = new THREE.Shape();
  s.moveTo(x - 0.05, -3.4);
  s.quadraticCurveTo(
    x + lean * 0.5,
    -3.4 + h * 0.6,
    x + lean,
    -3.4 + h,
  );
  s.quadraticCurveTo(
    x + lean * 0.5 + 0.06,
    -3.4 + h * 0.6,
    x + 0.05,
    -3.4,
  );
  reeds.add(cut(s, 1.2));
}
world.add(far, mid, ground, reeds);
const DURATION = 13,
  HOLD = 4; // seconds of film, and a rest before it starts again
const ease = (u) => u * u * (3 - 2 * u);
const BASE = {
  pelvis: 0,
  chest: 0,
  neck: 0,
  head: 0,
  armA: 0,
  foreA: 0,
  handA: 0,
  armB: 0,
  foreB: 0,
  handB: 0,
  thighA: 0,
  shinA: 0,
  footA: 0,
  thighB: 0,
  shinB: 0,
  footB: 0,
};
// Poses: an angle for every hinge (0 is the rest pose; a positive angle
// turns a piece counter-clockwise, away from the way he faces).
const SIT = {
  ...BASE,
  neck: 0.05,
  head: 0.2,
  armA: 0.35,
  foreA: 2.1,
  handA: 0.2,
  armB: 0.9,
  foreB: 0.8,
  thighA: 1.75,
  shinA: -2.95,
  footA: 1.2,
  thighB: 1.55,
  shinB: -2.8,
  footB: 1.25,
};
const LOOK = { ...SIT, neck: 0.15, head: 0.55, armA: 0.45, foreA: 1.9 }; // chin up: the moon has cleared the hills
const LEAN = {
  ...SIT,
  chest: -0.2,
  neck: 0.1,
  head: 0.35,
  armA: 0.9,
  foreA: 0.5,
  armB: 1.0,
  foreB: 0.4,
  thighA: 1.85,
  shinA: -3.0,
}; // a hand on each knee, to push
const HALF = {
  ...BASE,
  chest: -0.45,
  neck: 0.1,
  head: 0.3,
  armA: 1.0,
  foreA: 0.4,
  armB: 1.1,
  foreB: 0.35,
  thighA: 1.15,
  shinA: -1.8,
  footA: 0.65,
  thighB: 1.05,
  shinB: -1.7,
  footB: 0.6,
};
const STAND = {
  ...BASE,
  chest: 0.03,
  neck: 0.05,
  head: 0.35,
  armA: 0.15,
  foreA: 0.25,
  armB: -0.15,
  foreB: 0.2,
  thighA: 0.1,
  shinA: -0.05,
  footA: -0.05,
  thighB: -0.1,
  shinB: -0.05,
};
const REACH = {
  ...BASE,
  chest: -0.16,
  neck: 0.1,
  head: 0.5,
  armA: 2.35,
  foreA: 0.12,
  handA: 0.12,
  armB: -0.9,
  foreB: 0.3,
  thighA: 0.2,
  shinA: -0.25,
  footA: 0.3,
  thighB: -0.15,
  shinB: -0.05,
};
const STRETCH = {
  ...REACH,
  chest: -0.26,
  head: 0.65,
  armA: 2.55,
  handA: 0.3,
  thighA: 0.3,
  shinA: -0.3,
  footA: 0.9,
  thighB: -0.1,
}; // on tiptoe: still too far
const LUNGE = {
  ...BASE,
  chest: -0.5,
  neck: 0.1,
  head: 0.55,
  armA: 2.85,
  foreA: 0.1,
  armB: 2.55,
  foreB: 0.2,
  thighA: 0.75,
  shinA: -0.45,
  footA: 0.2,
  thighB: -0.55,
  shinB: -0.9,
  footB: 0.5,
}; // a step after the moon
const TRIP = {
  ...LUNGE,
  chest: -0.8,
  head: 0.2,
  neck: 0,
  armA: 3.0,
  foreA: 0.3,
  armB: 2.4,
  thighA: 0.9,
  shinA: -0.5,
  thighB: -1.1,
  shinB: -0.3,
  footB: 0.9,
}; // a foot catches
const TUCK = {
  ...BASE,
  chest: -0.7,
  neck: -0.2,
  head: -0.5,
  armA: 0.9,
  foreA: 2.3,
  armB: 0.8,
  foreB: 2.2,
  thighA: 2.2,
  shinA: -2.7,
  footA: 1.0,
  thighB: 2.0,
  shinB: -2.5,
  footB: 0.9,
}; // knees to the chest, in the air
const OPEN = {
  ...BASE,
  chest: 0.1,
  neck: 0.05,
  head: 0.3,
  armA: 2.2,
  foreA: 0.15,
  handA: 0.1,
  armB: 2.6,
  foreB: 0.1,
  thighA: 0.5,
  shinA: -0.2,
  footA: 0.2,
  thighB: -0.5,
  shinB: -0.15,
  footB: -0.2,
};
const DRIFT = { ...OPEN, armA: 2.0, armB: 2.5 };
// A film made on threes: the puppet is moved, photographed, held for
// three frames of the 24 a second, moved again. Halting, a little
// hesitant: the keys hold (the same pose twice) where he thinks, and
// move quickly where he lunges.
//            time  pose    hip height  tilt   forward  lift
const KEYS = [
  [0, SIT, 0.14, 0, 0, 0],
  [1.6, LOOK, 0.14, 0, 0, 0],
  [2.4, LOOK, 0.14, 0, 0, 0],
  [2.9, LEAN, 0.14, 0, 0, 0],
  [3.4, LEAN, 0.14, 0, 0, 0],
  [3.9, HALF, 0.95, 0, 0, 0],
  [4.2, HALF, 1.0, 0, 0, 0],
  [4.8, STAND, 1.75, 0, 0, 0],
  [5.4, STAND, 1.75, 0, 0, 0],
  [6.2, REACH, 1.78, 0, 0, 0],
  [7.6, REACH, 1.78, 0, 0, 0],
  [8.4, STRETCH, 1.8, 0, 0, 0],
  [9.1, STRETCH, 1.8, 0, 0, 0],
  [9.7, LUNGE, 1.68, -0.3, 0.7, 0],
  [10.2, TRIP, 1.6, -0.9, 1.1, 0],
  [11.0, TUCK, 1.5, -3.5, 1.5, 0.9],
  [12.0, OPEN, 1.5, -6.3, 1.8, 1.2],
  [DURATION, DRIFT, 1.5, -6.5, 1.9, 1.5],
];
const track = (t) => {
  // the pose, hip height, tilt, step forward and lift at time t
  let i = 0;
  while (i < KEYS.length - 2 && t > KEYS[i + 1][0]) i++;
  const [t0, p0, h0, r0, f0, l0] = KEYS[i],
    [t1, p1, h1, r1, f1, l1] = KEYS[i + 1];
  const lin = Math.min(1, Math.max(0, (t - t0) / (t1 - t0))),
    u = t0 >= 10.2 ? lin : ease(lin),
    mix = (a, b) => a + (b - a) * u; // (in the air he turns steadily)
  return {
    pose: Object.fromEntries(
      Object.keys(BASE).map((k) => [k, mix(p0[k], p1[k])]),
    ),
    hip: mix(h0, h1),
    tilt: mix(r0, r1),
    step: mix(f0, f1),
    lift: mix(l0, l1),
  };
};
const hash = (a, b) => {
  const x = Math.sin(a * 127.1 + b * 311.7) * 43758.5453;
  return x - Math.floor(x);
};

// The sky: colours at times, and the moon's climb.
const UP = 10.0; // when he leaves the ground
const SKY = [
  [0, '#f0d9a0'],
  [3, '#e6c394'],
  [6, '#c49c8c'],
  [8.2, '#8a6f8a'],
  [9.6, '#4a4678'],
  [11, '#2a3366'],
  [12.5, '#141b45'],
  [DURATION, '#0d1235'],
].map(([t, c]) => [t, new THREE.Color(c)]); // dusk, a little at a time
const sky = (t) => {
  let i = 0;
  while (i < SKY.length - 2 && t > SKY[i + 1][0]) i++;
  const [a, ca] = SKY[i],
    [b, cb] = SKY[i + 1];
  return ca
    .clone()
    .lerp(cb, ease(Math.min(1, Math.max(0, (t - a) / (b - a)))));
};
const dark = (t) => ease(Math.min(1, t / 12)); // how dark it is: by the time he is in the air it is nearly night

home.set(-3.0, -2.35);
const dune = new THREE.Shape();
dune.moveTo(-6, -3.6);
dune.quadraticCurveTo(-4.4, -2.4, -3.0, -2.4);
dune.quadraticCurveTo(-1.4, -2.4, -0.2, -3.6);
world.add(cut(dune, -0.2));
const figure = new THREE.MeshBasicMaterial({
  color: 0x0b0a0a,
  transparent: true,
  side: THREE.DoubleSide,
});
for (const n of Object.values(node)) n.mesh.material = figure; // the puppet's paper has a material of its own, so it can be styled alone
const glowTex = (() => {
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const g = c.getContext('2d'),
    r = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  r.addColorStop(0, 'rgba(255,255,255,1)');
  r.addColorStop(0.25, 'rgba(255,255,255,0.7)');
  r.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = r;
  g.fillRect(0, 0, 64, 64);
  return new THREE.CanvasTexture(c);
})();
const starMat = () =>
  new THREE.MeshBasicMaterial({
    map: glowTex,
    transparent: true,
    depthWrite: false,
    depthTest: false,
    blending: THREE.AdditiveBlending,
  });
for (const n of Object.values(node)) {
  // each hinge can glow: a star in the paper's own place
  n.star = new THREE.Mesh(
    new THREE.PlaneGeometry(0.22, 0.22),
    starMat(),
  );
  n.star.position.z = 0.4;
  n.group.add(n.star);
  n.dot = new THREE.Mesh(
    new THREE.CircleGeometry(0.05, 20),
    new THREE.MeshBasicMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 0,
    }),
  ); // the ring fills in as the paper goes
