  shinA: -0.3,
  footA: 0.9,
  thighB: -0.1,
}; // on tiptoe: still too far
const LUNGE = {
  ...BASE,
  chest: -0.5,
  neck: 0.1,
  head: 0.55,
  armA: 2.85,
  foreA: 0.1,
  armB: 2.55,
  foreB: 0.2,
  thighA: 0.75,
  shinA: -0.45,
  footA: 0.2,
  thighB: -0.55,
  shinB: -0.9,
  footB: 0.5,
}; // a step after the moon
const TRIP = {
  ...LUNGE,
  chest: -0.8,
  head: 0.2,
  neck: 0,
  armA: 3.0,
  foreA: 0.3,
  armB: 2.4,
  thighA: 0.9,
  shinA: -0.5,
  thighB: -1.1,
  shinB: -0.3,
  footB: 0.9,
}; // a foot catches
const TUCK = {
  ...BASE,
  chest: -0.7,
  neck: -0.2,
  head: -0.5,
  armA: 0.9,
  foreA: 2.3,
  armB: 0.8,
  foreB: 2.2,
  thighA: 2.2,
  shinA: -2.7,
  footA: 1.0,
  thighB: 2.0,
  shinB: -2.5,
  footB: 0.9,
}; // knees to the chest, in the air
const OPEN = {
  ...BASE,
  chest: 0.1,
  neck: 0.05,
  head: 0.3,
  armA: 2.2,
  foreA: 0.15,
  handA: 0.1,
  armB: 2.6,
  foreB: 0.1,
  thighA: 0.5,
  shinA: -0.2,
  footA: 0.2,
  thighB: -0.5,
  shinB: -0.15,
  footB: -0.2,
};
const DRIFT = { ...OPEN, armA: 2.0, armB: 2.5 };
// A film made on threes: the puppet is moved, photographed, held for
// three frames of the 24 a second, moved again. Halting, a little
// hesitant: the keys hold (the same pose twice) where he thinks, and
// move quickly where he lunges.
//            time  pose    hip height  tilt   forward  lift
const KEYS = [
  [0, SIT, 0.14, 0, 0, 0],
  [1.6, LOOK, 0.14, 0, 0, 0],
  [2.4, LOOK, 0.14, 0, 0, 0],
  [2.9, LEAN, 0.14, 0, 0, 0],
  [3.4, LEAN, 0.14, 0, 0, 0],
  [3.9, HALF, 0.95, 0, 0, 0],
  [4.2, HALF, 1.0, 0, 0, 0],
  [4.8, STAND, 1.75, 0, 0, 0],
  [5.4, STAND, 1.75, 0, 0, 0],
  [6.2, REACH, 1.78, 0, 0, 0],
  [7.6, REACH, 1.78, 0, 0, 0],
  [8.4, STRETCH, 1.8, 0, 0, 0],
  [9.1, STRETCH, 1.8, 0, 0, 0],
  [9.7, LUNGE, 1.68, -0.3, 0.7, 0],
  [10.2, TRIP, 1.6, -0.9, 1.1, 0],
  [11.0, TUCK, 1.5, -3.5, 1.5, 0.9],
  [12.0, OPEN, 1.5, -6.3, 1.8, 1.2],
  [DURATION, DRIFT, 1.5, -6.5, 1.9, 1.5],
];
const track = (t) => {
  // the pose, hip height, tilt, step forward and lift at time t
  let i = 0;
  while (i < KEYS.length - 2 && t > KEYS[i + 1][0]) i++;
  const [t0, p0, h0, r0, f0, l0] = KEYS[i],
    [t1, p1, h1, r1, f1, l1] = KEYS[i + 1];
  const lin = Math.min(1, Math.max(0, (t - t0) / (t1 - t0))),
    u = t0 >= 10.2 ? lin : ease(lin),
    mix = (a, b) => a + (b - a) * u; // (in the air he turns steadily)
  return {
    pose: Object.fromEntries(
      Object.keys(BASE).map((k) => [k, mix(p0[k], p1[k])]),
    ),
    hip: mix(h0, h1),
    tilt: mix(r0, r1),
    step: mix(f0, f1),
    lift: mix(l0, l1),
  };
};
const hash = (a, b) => {
  const x = Math.sin(a * 127.1 + b * 311.7) * 43758.5453;
  return x - Math.floor(x);
};

// The sky: colours at times, and the moon's climb.
const UP = 10.0; // when he leaves the ground
const SKY = [
  [0, '#f0d9a0'],
  [3, '#e6c394'],
  [6, '#c49c8c'],
  [8.2, '#8a6f8a'],
  [9.6, '#4a4678'],
  [11, '#2a3366'],
  [12.5, '#141b45'],
  [DURATION, '#0d1235'],
].map(([t, c]) => [t, new THREE.Color(c)]); // dusk, a little at a time
const sky = (t) => {
  let i = 0;
  while (i < SKY.length - 2 && t > SKY[i + 1][0]) i++;
  const [a, ca] = SKY[i],
    [b, cb] = SKY[i + 1];
  return ca
    .clone()
    .lerp(cb, ease(Math.min(1, Math.max(0, (t - a) / (b - a)))));
};
const dark = (t) => ease(Math.min(1, t / 12)); // how dark it is: by the time he is in the air it is nearly night

home.set(-3.0, -2.35);
const dune = new THREE.Shape();
dune.moveTo(-6, -3.6);
dune.quadraticCurveTo(-4.4, -2.4, -3.0, -2.4);
dune.quadraticCurveTo(-1.4, -2.4, -0.2, -3.6);
world.add(cut(dune, -0.2));
const figure = new THREE.MeshBasicMaterial({
  color: 0x0b0a0a,
  transparent: true,
  side: THREE.DoubleSide,
});
for (const n of Object.values(node)) n.mesh.material = figure; // the puppet's paper has a material of its own, so it can be styled alone
const glowTex = (() => {
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const g = c.getContext('2d'),
    r = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  r.addColorStop(0, 'rgba(255,255,255,1)');
  r.addColorStop(0.25, 'rgba(255,255,255,0.7)');
  r.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = r;
  g.fillRect(0, 0, 64, 64);
  return new THREE.CanvasTexture(c);
})();
const starMat = () =>
  new THREE.MeshBasicMaterial({
    map: glowTex,
    transparent: true,
    depthWrite: false,
    depthTest: false,
    blending: THREE.AdditiveBlending,
  });
for (const n of Object.values(node)) {
  // each hinge can glow: a star in the paper's own place
  n.star = new THREE.Mesh(
    new THREE.PlaneGeometry(0.22, 0.22),
    starMat(),
  );
  n.star.position.z = 0.4;
  n.group.add(n.star);
  n.dot = new THREE.Mesh(
    new THREE.CircleGeometry(0.05, 20),
    new THREE.MeshBasicMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 0,
    }),
  ); // the ring fills in as the paper goes
  n.dot.position.z = 0.3;
  n.group.add(n.dot);
}

// Sky stars: each has a place and a time it appears. Shooting stars: a
// few, at random times, each a streak that fades.
let rnd = 1;
const rand = () => {
  rnd = (rnd * 16807) % 2147483647;
  return (rnd - 1) / 2147483646;
};
let skyStars = [],
  streaks = [];
const reseed = () => {
  rnd = 1 + Math.floor(Math.random() * 1e6);
  skyStars.forEach((m) => {
    world.remove(m);
  });
  streaks.forEach((m) => world.remove(m.mesh));
  skyStars = Array.from({ length: 110 }, () => {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), starMat());
    m.position.set(
      (((rand() - 0.5) * FRAME * W) / H) * 1.1,
      -0.2 + rand() * (FRAME / 2 + 0.2),
      -4.8,
    );
    m.userData = {
      at: 1 + 11 * Math.pow(rand(), 1.4),
      size: 0.06 + 0.14 * rand() * rand(),
      twinkle: rand() * 6,
    };
    world.add(m);
    return m;
  });
  streaks = Array.from({ length: 6 }, () => {
    const mesh = new THREE.Line(
      new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(),
        new THREE.Vector3(),
      ]),
      new THREE.LineBasicMaterial({
        color: 0xffffff,
        transparent: true,
        depthTest: false,
      }),
    );
    mesh.position.z = -4.7;
    world.add(mesh);
    return {
      mesh,
      at: 2 + rand() * 14,
      x: (((rand() - 0.2) * FRAME * W) / H) * 0.5,
      y: 0.8 + rand() * 2.4,
      a: -0.35 - rand() * 0.5,
    };
  });
};
const showSky = (t, night, live) => {
  for (const m of skyStars) {
    const d = m.userData,
      on = ease(Math.min(1, Math.max(0, (t - d.at) / 1.5))) * night;
    m.material.opacity =
      on * (0.65 + 0.35 * Math.sin(live * 3 + d.twinkle));
    m.scale.setScalar(
      d.size * (0.8 + 0.4 * Math.sin(live * 2 + d.twinkle)),
    );
  }
  for (const s of streaks) {
    const u = (t - s.at) / 0.8;
    s.mesh.visible = u > 0 && u < 1 && night > 0.3;
    if (!s.mesh.visible) continue;
    const dx = Math.cos(s.a),
      dy = Math.sin(s.a),
      head = u * 3.4,
      tail = Math.max(0, head - 1.1);
    s.mesh.geometry.setFromPoints([
      new THREE.Vector3(s.x + dx * tail, s.y + dy * tail, 0),
      new THREE.Vector3(s.x + dx * head, s.y + dy * head, 0),
    ]);
    s.mesh.material.opacity = (1 - u) * night;
  }
};

// --- the transport: the film's clock, and the shot.
const LENGTH = DURATION + HOLD;
let pos = 0, last = performance.now();
const target = new THREE.WebGLRenderTarget(W, H);
const filmMat = new THREE.ShaderMaterial({
  uniforms: { tex: { value: target.texture }, time: { value: 0 }, grain: { value: 0 }, flicker: { value: 0 }, weave: { value: 0 }, vignette: { value: 0 }, dust: { value: 0 } },
  vertexShader: 'varying vec2 vUv; void main() { vUv = uv; gl_Position = vec4(position.xy, 0.0, 1.0); }',
  fragmentShader: `
    varying vec2 vUv; uniform sampler2D tex; uniform float time, grain, flicker, weave, vignette, dust;
    float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
    void main() {
      float frame = floor(time * 12.0);                                         // the film runs at 12 frames a second
      vec2 shift = weave * vec2(hash(vec2(frame, 1.0)) - 0.5, hash(vec2(frame, 2.0)) - 0.5);
      vec3 c = texture2D(tex, vUv + shift).rgb;
      c += grain * (hash(vUv * 900.0 + frame) - 0.5);                           // grain: new noise every frame
      c *= 1.0 + flicker * (hash(vec2(frame, 3.0)) - 0.5) * 2.0;                // flicker
      c *= 1.0 - vignette * smoothstep(0.35, 0.95, length(vUv - 0.5) * 1.4);    // dark corners
      float speck = step(0.9993, hash(floor(vUv * 220.0) + frame));             // dust: a few pale specks
      c = mix(c, vec3(0.92), speck * dust);
      gl_FragColor = vec4(c, 1.0);
    }`,
});
const picture = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), filmMat);
picture.frustumCulled = false;
scene.add(picture);
// the host disposes only its own scene when the node is re-evaluated or removed, so it also releases the paper world
const releaseHost = picture.geometry.dispose.bind(picture.geometry);
picture.geometry.dispose = () => {
  world.traverse((o) => {
    o.geometry?.dispose();
    for (const m of Array.isArray(o.material) ? o.material : [o.material]) { m?.map?.dispose(); m?.dispose(); }
  });
  target.dispose(); glowTex.dispose(); releaseHost();
};

tick(() => {
  const now = performance.now(), dt = Math.min(0.25, (now - last) / 1000);
  last = now;
  pos += dt;
  if (pos > LENGTH) { pos = 0; reseed(); } // new random stars each time round
  if (!skyStars.length) reseed();
  const t = pos, clock = Math.min(t, DURATION);
  // the puppet is photographed a frame at a time: its pose changes only on an exposure, and each is a little imprecise
  const frameNo = Math.floor(clock * fps), still = frameNo / fps;
  const k = track(still), night = dark(clock);
  Object.keys(k.pose).forEach((id, i) => {
    node[id].group.rotation.z = k.pose[id] + 0.012 * (hash(frameNo, i) - 0.5);
  });
  if (still > 7.6 && still < 9.4) node.armA.group.rotation.z += 0.012 * Math.sin(frameNo * 2.3); // reaching: the slightest tremble
  node.pelvis.group.position.y = k.hip;
  const after = Math.max(0, t - DURATION); // after the last key the film does not stop: he keeps drifting, slowly
  const spin = k.tilt - after * 0.015,
    air = ease(Math.min(1, Math.max(0, (clock - 10) / 0.5))),
    pivot = air * k.hip * puppet.scale.x;
  // on the ground he tips about his feet; in the air (the somersault) about his hips, which follow their own path
  puppet.rotation.z = spin;
  puppet.position.set(home.x + k.step + after * 0.03 + pivot * Math.sin(spin), home.y + k.lift + after * 0.05 + pivot - pivot * Math.cos(spin), 0);
  puppet.updateMatrixWorld(true);
  // The moon rises slowly, up and to the right, a frame at a time; it does not wait for him: it slips out of the sky as he trips.
  const q = Math.floor(clock * 12) / 12;
  const mx = -2.0 + 0.244 * q,
    my = q < 4.5 ? -3.4 + 0.667 * q : q < 9 ? -0.4 + 0.756 * (q - 4.5) : 3.0 + 0.756 * (q - 9) + 0.5 * Math.pow(q - 9, 2);
  moonDisc.visible = true;
  moonDisc.position.set(mx, my, -4.9);
  // his gaze follows the moon, and so does the reaching arm: pointed at it, and always a little short
  const eyeAt = node.head.group.getWorldPosition(new THREE.Vector3());
  const want = Math.min(1.25, Math.max(-0.1, Math.atan2(my - eyeAt.y, mx - eyeAt.x)));
  const lean = puppet.rotation.z + node.pelvis.group.rotation.z + node.chest.group.rotation.z;
  const watch = 1 - ease(Math.min(1, Math.max(0, (still - 10) / 0.4))),
    turn = Math.max(-0.5, Math.min(1.05, want - lean));
  node.neck.group.rotation.z = k.pose.neck + (0.35 * turn - k.pose.neck) * watch + 0.012 * (hash(frameNo, 20) - 0.5);
  node.head.group.rotation.z = k.pose.head + (0.65 * turn - k.pose.head) * watch + 0.012 * (hash(frameNo, 21) - 0.5);
  const hand = node.armA.group.getWorldPosition(new THREE.Vector3());
  let aim = Math.atan2(my - hand.y, mx - hand.x) + Math.PI / 2 - lean;
  aim = Math.atan2(Math.sin(aim), Math.cos(aim));
  const reach = ease(Math.min(1, Math.max(0, (still - 5.2) / 1.0))) * (1 - ease(Math.min(1, Math.max(0, (still - 10) / 0.5))));
  node.armA.group.rotation.z += (aim - node.armA.group.rotation.z) * reach;
  node.foreA.group.rotation.z *= 1 - reach * 0.8;
  const both = reach * ease(Math.min(1, Math.max(0, (still - 9.3) / 0.4)));
  node.armB.group.rotation.z += (aim - 0.35 - node.armB.group.rotation.z) * both;
  // the paper goes a piece at a time, as if each were lifted off the table between exposures; the white hinge is left, a star
  const ORDER = ['handA', 'handB', 'footA', 'footB', 'foreA', 'foreB', 'shinA', 'shinB', 'armA', 'armB', 'thighA', 'thighB', 'head', 'neck', 'chest', 'pelvis'];
  for (const n of Object.values(node)) {
    const out = UP + 1.0 + ORDER.indexOf(n.id) * 0.12, gone1 = still >= out;
    n.mesh.visible = !gone1;
    n.pin.visible = true;
    n.dot.material.opacity = gone1 ? 1 : 0;
    n.star.material.opacity = gone1 ? 0.4 : 0;
    n.star.scale.setScalar(0.35 + 0.6 * (0.85 + 0.15 * Math.sin(t * 4 + n.depth * 2)));
  }
  reeds.children.forEach((r, i) => { r.rotation.z = 0.02 * Math.sin(t * 1.3 + i); });
  // the sky, the moon, the hills' colour
  lightbox.material.color.copy(sky(clock));
  mid.material.color.setHex(0x1a1610).lerp(new THREE.Color(0x060810), night);
  showSky(clock, night, t);
  // the scene, into the picture; the host then draws the picture through the film-look shader
  filmMat.uniforms.time.value = now / 1000;
  filmMat.uniforms.grain.value = 0.22;
  filmMat.uniforms.flicker.value = 0.03;
  filmMat.uniforms.weave.value = 0.002;
  filmMat.uniforms.vignette.value = 0.6;
  filmMat.uniforms.dust.value = 0.15;
  renderer.setRenderTarget(target);
  renderer.render(world, film);
  renderer.setRenderTarget(null);
});
